import type { Href } from 'expo-router';

// Cast: typed routes are regenerated by `expo start`, so new routes may be missing until then.
export const ALARM_SETUP_HREF = '/controls/alarm-setup' as Href;
export const ALARM_SOUND_HREF = '/controls/alarm-sound' as Href;
export function alarmEditHref(id?: string): Href {
  return (id ? `/controls/alarm-edit?id=${encodeURIComponent(id)}` : '/controls/alarm-edit') as Href;
}
